{"ASK_WINTER","reg=civilian,family,worker,rescue|st=careful",{"It's winter, it's cold"}},
{"ASK_WINTER","reg=raider|st=neutral,careful",{"Winter here? Brutal, and I love it, the weak freeze and the strong rob them"}},
{"ASK_WINTER","reg=gang|st=neutral,careful",{"Winter's a killer, the cold finds you in every crack"}},
{"ASK_WINTER","reg=club|st=neutral,careful|world=road",{"Winter's long, {g:brother|sister}, and the roads are slick, no riding"}},
{"ASK_WINTER","reg=crime|st=neutral,careful",{"Winter is a season of hardship and opportunity"}},
{"ASK_WINTER","reg=prison|st=neutral,careful",{"Winter's the worst, damn thing follows you indoors too"}},
{"ASK_WINTER","reg=outlaw|st=neutral,careful",{"Winter is hard in the hills, but the dead freeze stiff"}},
{"ASK_WINTER","reg=law|st=neutral,careful",{"Winter conditions are dangerous, prepare accordingly"}},
